```sql
-- Начинается на A
SELECT name FROM users WHERE name LIKE 'A%';

-- Заканчивается на A
SELECT name FROM users WHERE name LIKE '%A';
```

```sql
SELECT * FROM users WHERE email IS NULL;

SELECT * FROM users WHERE email IS NOT NULL;
```

```sql
SELECT COUNT(*) AS total_users FROM users;

SELECT COUNT(email) AS with_email FROM users;
```

